stateDiagram
  state Running {
    direction LR
    state A {
      direction TB
      state "Two words" as Idle
      state "Two words" as Wait1
    }
    note right of Long_name : Ünï note
    classDef big stroke:#333
  }
  state Long_name {
    click Long_name "https://example.com/Long_name"
    --
    classDef hot color:red;fill:#0a0
    state Long_name {
      note right of A : Ünï note
      Wait1 --> Idle : $$x^2$$
    }
  }
  state Ünï {
    state Running <<choice>>
    style Ünï fill:#f96
  }
  state Done {
    class Long_name big
    --
    classDef hot fill:#f96
    click Running href "https://example.com/Running" "tip"
  }
  state A {
    C --> C : self
    click Ünï href "https://example.com/Ünï" "tip"
